function csvCell(value) {
  const text = Array.isArray(value) ? value.map((item) => typeof item === "object" ? JSON.stringify(item) : item).join(" | ") : String(value ?? "");
  return `"${text.replaceAll('"', '""')}"`;
}

function csv(rows, selectedHeaders = headers) {
  return [selectedHeaders.map(csvCell).join(","), ...rows.map((item) => selectedHeaders.map((header) => csvCell(item[header])).join(","))].join("\n") + "\n";
}

